function ownAccountAdministrationSnapshot(PDO $db):array
{
    $out=[];foreach($db->query('SHOW TABLES')->fetchAll(PDO::FETCH_COLUMN) as $table){$columns=$db->query('SHOW COLUMNS FROM `'.$table.'`')->fetchAll(PDO::FETCH_COLUMN);$selection='`'.implode('`,`',$columns).'`';$rows=[];foreach($db->query('SELECT '.$selection.' FROM `'.$table.'`')->fetchAll(PDO::FETCH_ASSOC) as $row){$hash=hash('sha256',serialize($row));$rows[$hash]=($rows[$hash]??0)+1;}$out[$table]=['columns'=>$selection,'rows'=>$rows];}return $out;
}
function ownAccountAdministrationOriginals(PDO $db,array $original):void
